<template>
  <PageHero
    tag="Contact"
    title="お問い合わせ"
    subtitle="アプリ開発・DevOps・Web制作のご相談はお気軽にどうぞ"
    :visible="pageVisible"
  />

  <!-- ===== Form Section ===== -->
  <section class="form-section">
    <v-container>
      <div class="form-wrap" :class="{ visible: pageVisible }">
        <v-form ref="formRef" v-model="valid" @submit.prevent="handleSubmit">

          <div class="field-group">
            <label class="field-label" for="contact-subject"
              >件名 <span class="required">必須</span></label
            >
            <v-text-field
              id="contact-subject"
              v-model="form.subject"
              :rules="[required]"
              placeholder="例：アプリ開発のご相談"
              variant="outlined"
              density="comfortable"
              hide-details="auto"
              class="dark-field"
            />
          </div>

          <div class="field-group">
            <label class="field-label" for="contact-organization"
              >会社名・団体名</label
            >
            <v-text-field
              id="contact-organization"
              v-model="form.organization"
              placeholder="例：株式会社〇〇"
              variant="outlined"
              density="comfortable"
              hide-details="auto"
              class="dark-field"
            />
          </div>

          <div class="field-row">
            <div class="field-group">
              <label class="field-label" for="contact-name"
                >お名前 <span class="required">必須</span></label
              >
              <v-text-field
                id="contact-name"
                v-model="form.name"
                :rules="[required]"
                placeholder="例：山田 太郎"
                variant="outlined"
                density="comfortable"
                hide-details="auto"
                class="dark-field"
              />
            </div>

            <div class="field-group">
              <label class="field-label" for="contact-mail"
                >メールアドレス <span class="required">必須</span></label
              >
              <v-text-field
                id="contact-mail"
                v-model="form.mail"
                :rules="[required, emailRule]"
                placeholder="例：example@mail.com"
                variant="outlined"
