<script setup>
import { ref, reactive, onMounted, nextTick } from "vue";
import PageHero from "@/components/PageHero.vue";

const pageVisible = ref(false);
const formRef = ref(null);
const valid = ref(false);
const dialog = ref(false);
const isLoading = ref(false);
const errorMessage = ref("");

// Google Forms の URL / entry ID は .env で管理（ビルド時に埋め込まれる）
const FORM_URL = process.env.VUE_APP_CONTACT_FORM_URL;

const ENTRY_MAP = {
  subject: process.env.VUE_APP_CONTACT_ENTRY_SUBJECT,
  organization: process.env.VUE_APP_CONTACT_ENTRY_ORGANIZATION,
  name: process.env.VUE_APP_CONTACT_ENTRY_NAME,
  mail: process.env.VUE_APP_CONTACT_ENTRY_MAIL,
  content: process.env.VUE_APP_CONTACT_ENTRY_CONTENT,
};

const INITIAL_FORM = () => ({
  subject: "",
  organization: "",
  name: "",
  mail: "",
  content: "",
});

const form = reactive(INITIAL_FORM());

const snsLinks = [
  {
    title: "代表のX",
    subtitle: "DMからお気軽にお問い合わせください",
    icon: "mdi-alpha-x-box",
    href: "https://twitter.com/KeitaKozuka",
    color: "var(--c-text-2)",
  },
  {
    title: "代表のFacebook",
    subtitle: "DMからお気軽にお問い合わせください",
    icon: "mdi-facebook",
    href: "https://www.facebook.com/keita.kozuka",
    color: "#60a5fa",
  },
];

const agreed = ref(false);

const required = (v) => !!v || "必須項目です";
const emailRule = (v) => /.+@.+\..+/.test(v) || "メールアドレスの形式が正しくありません";
const consentRule = (v) => !!v || "プライバシーポリシーへの同意が必要です";

function trackSubmit(status) {
  window.gtag?.("event", "contact_form_submit", { status });
}

async function handleSubmit() {
  if (!valid.value) return;
  isLoading.value = true;
  errorMessage.value = "";

  const params = new URLSearchParams();
  for (const key in form) {
    params.append(ENTRY_MAP[key], form[key]);
  }

  try {
    // no-cors: レスポンスは読めないが、オフライン・DNS障害等の
    // ネットワークエラー時は reject されるため送信失敗を検知できる
    await fetch(FORM_URL, {
      method: "POST",
      mode: "no-cors",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: params,
    });
    trackSubmit("success");
    Object.assign(form, INITIAL_FORM());
    agreed.value = false;
    // 値のクリアで required ルールが発火するため、反映後にバリデーション表示をリセット
    await nextTick();
    formRef.value?.resetValidation();
    dialog.value = true;
  } catch {
    trackSubmit("error");
    errorMessage.value = "送信に失敗しました。しばらくしてからもう一度お試しください。";
  } finally {
    isLoading.value = false;
  }
}

onMounted(() => {
  setTimeout(() => (pageVisible.value = true), 200);
});
</script>

